from cart import add_item

def test_with_explicit_basket():
    # Passes before fix
    my_basket = ["apple"]
    assert add_item("banana", my_basket) == ["apple", "banana"]

def test_first_call_default():
    assert add_item("orange") == ["orange"]

def test_second_call_default_isolation():
    # Default list should not retain previously added items
    assert add_item("grape") == ["grape"]

def test_third_call_default_isolation():
    assert add_item("melon") == ["melon"]
